#pragma once
// Scene "space" (space_rtx_wallpaper.md): rotating Earth, two LEO satellites orbiting
// 16x faster than the Earth spins, directional Sun and a slow "cinematic drift" camera.
#include "Scene.h"
#include "Space.hlsl.h"   // generated by dxc: g_pSpace[]

class SpaceScene : public Scene
{
    // Must match SceneConstantBuffer in shaders/Space.hlsl.
    struct Constants
    {
        CameraConstants camera;
        DirectX::XMFLOAT4 sunDirection;     // xyz towards the sun, w = intensity
        DirectX::XMFLOAT4 earthTransform;   // w = rotation (radians)
        DirectX::XMFLOAT4 satellitePos[2];
        DirectX::XMFLOAT4 params;           // x = time
    };

    float m_timeAcc = 0.0f;

    // Time scales from the design doc.
    static constexpr float CAMERA_SPEED = 0.05f;                     // cinematic drift
    static constexpr float EARTH_ROT_SPEED = 0.1f;                   // Earth spin
    static constexpr float SATELLITE_SPEED = EARTH_ROT_SPEED * 16.0f; // LEO: 16 orbits per Earth rotation
    static constexpr float EARTH_RADIUS = 10.0f;
    // The doc orbits the camera at 20 units looking at the Earth's centre; with a radius-10 Earth
    // that fills the whole screen, so we pull back a bit and frame the Earth off-centre.
    static constexpr float CAMERA_DISTANCE = 27.0f;
    static constexpr float FRAME_OFFSET = 8.0f;
    static constexpr float SATELLITE_SCALE = 0.7f;

    static DirectX::XMVECTOR SatellitePosition(int i, float t)
    {
        using namespace DirectX;
        if (i == 0)
        {
            // Satellite 1: equatorial / slightly inclined orbit.
            const float r = 12.0f, a = t * SATELLITE_SPEED;
            return XMVectorSet(sinf(a) * r, sinf(a * 0.5f) * 2.0f, cosf(a) * r, 0);
        }
        // Satellite 2: polar orbit, out of phase and a bit slower.
        const float r = 13.5f, a = t * SATELLITE_SPEED * 0.8f + 3.1415f;
        return XMVectorSet(sinf(a) * 3.0f, cosf(a) * r, sinf(a) * r, 0);
    }

public:
    const wchar_t* Name() const override { return L"space"; }
    D3D12_SHADER_BYTECODE Library() const override { return { g_pSpace, sizeof(g_pSpace) }; }
    UINT InstanceCount() const override { return 3; }
    UINT MaxRecursion() const override { return 4; }   // MAX_DEPTH (3) + 1

    std::vector<HitGroupDef> HitGroups() const override
    {
        return {
            { L"EarthHitGroup", L"EarthClosestHit", L"SphereIntersection" },
            { L"SatelliteHitGroup", L"SatelliteClosestHit", L"SatelliteIntersection" },
        };
    }

    std::vector<GeometryDef> Geometry() const override
    {
        GeometryDef earth;                       // unit sphere, scaled by the instance
        earth.aabb = { -1, -1, -1, 1, 1, 1 };
        GeometryDef satellite;                   // body + solar panels + antenna (boxes in the shader)
        satellite.aabb = { -2.55f, -0.8f, -0.45f, 2.55f, 0.8f, 0.45f };
        return { earth, satellite };
    }

    UINT Update(float deltaTime, void* constants, InstanceDef* instances) override
    {
        using namespace DirectX;
        Constants& cb = *static_cast<Constants*>(constants);
        m_timeAcc += deltaTime;
        const float t = m_timeAcc;

        // 1. Cinematic camera: slow orbit around the Earth, rising and sinking in Y.
        XMVECTOR eye = XMVectorSet(sinf(t * CAMERA_SPEED) * CAMERA_DISTANCE,
                                   cosf(t * CAMERA_SPEED * 0.5f) * 5.0f,
                                   cosf(t * CAMERA_SPEED) * CAMERA_DISTANCE, 0);
        XMVECTOR toCenter = XMVector3Normalize(XMVectorNegate(eye));
        XMVECTOR right = XMVector3Normalize(XMVector3Cross(toCenter, XMVectorSet(0, 1, 0, 0)));
        XMVECTOR target = XMVectorAdd(XMVectorScale(right, FRAME_OFFSET), XMVectorSet(0, 2.0f, 0, 0));
        cb.camera = MakeCamera(eye, target, 50.0f);

        // 2. Earth rotation (in W).
        cb.earthTransform = XMFLOAT4(0, 0, 0, t * EARTH_ROT_SPEED);

        // 3. Satellites, oriented with +Y away from the Earth and +Z along the velocity.
        instances[0] = InstanceDef{ 0, 0, 0 };
        instances[0].SetTranslationScale(0, 0, 0, EARTH_RADIUS);
        for (int i = 0; i < 2; i++)
        {
            XMVECTOR p = SatellitePosition(i, t);
            XMVECTOR vel = XMVectorSubtract(SatellitePosition(i, t + 0.01f), p);
            XMVECTOR y = XMVector3Normalize(p);
            XMVECTOR z = XMVector3Normalize(XMVectorSubtract(vel, XMVectorScale(y, XMVectorGetX(XMVector3Dot(vel, y)))));
            XMVECTOR x = XMVector3Cross(y, z);
            // Uniform scale keeps the satellites readable without dwarfing the Earth.
            x = XMVectorScale(x, SATELLITE_SCALE);
            y = XMVectorScale(y, SATELLITE_SCALE);
            z = XMVectorScale(z, SATELLITE_SCALE);
            XMStoreFloat4(&cb.satellitePos[i], p);
            cb.satellitePos[i].w = 1.0f;

            InstanceDef& inst = instances[1 + i];
            inst = InstanceDef{ 1, 1, (UINT)i };
            XMFLOAT3 ax, ay, az, pos;
            XMStoreFloat3(&ax, x);
            XMStoreFloat3(&ay, y);
            XMStoreFloat3(&az, z);
            XMStoreFloat3(&pos, p);
            // Columns = object axes in world space.
            float m[3][4] = { { ax.x, ay.x, az.x, pos.x }, { ax.y, ay.y, az.y, pos.y }, { ax.z, ay.z, az.z, pos.z } };
            memcpy(inst.transform, m, sizeof(m));
        }

        // 4. Sun: distant, static directional light.
        XMVECTOR sun = XMVector3Normalize(XMVectorSet(1.0f, 0.2f, -0.5f, 0));
        XMStoreFloat4(&cb.sunDirection, sun);
        cb.sunDirection.w = 2.6f;
        cb.params = XMFLOAT4(t, 0, 0, 0);
        return sizeof(Constants);
    }
};
